<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import {
  GROUP_TYPES,
  GROUP_TYPE_LABELS,
  GROUP_TYPE_DESCRIPTIONS,
  GROUP_NAME_MAX_LENGTH,
  validateGroupName,
  type GroupType,
} from '@/voice/GroupProtocol'

const emit = defineEmits<{ (event: 'channel-selected'): void }>()

const voiceStore = useVoiceStore()

/** The real SVC groups, shared with the mod, instead of a local dummy list. */
const groups = computed(() => voiceStore.groups)
const currentGroupId = computed(() => voiceStore.state.currentChannel)

const showCreateDialog = ref(false)
const newName = ref('')
const newType = ref<GroupType>('normal')
const newPersistent = ref(false)
const createError = ref<string | null>(null)
const busyGroupId = ref<string | null>(null)
const isCreating = ref(false)

/** Whatever went wrong last, so it can be shown next to the buttons. */
const actionError = ref<string | null>(null)

const canCreate = computed(() => newName.value.trim().length > 0 && !isCreating.value)

function typeLabel(type: string): string {
  const known = GROUP_TYPE_LABELS[type as GroupType]
  return known ?? GROUP_TYPE_LABELS.normal
}

function typeDescription(type: string): string {
  const known = GROUP_TYPE_DESCRIPTIONS[type as GroupType]
  return known ?? GROUP_TYPE_DESCRIPTIONS.normal
}

function participantLabel(group: { participants: number }): string {
  return group.participants === 1 ? '1 Person' : `${group.participants} Personen`
}

function openCreateDialog() {
  createError.value = null
  newName.value = ''
  newType.value = 'normal'
  newPersistent.value = false
  showCreateDialog.value = true
}

function closeCreateDialog() {
  if (isCreating.value) return
  showCreateDialog.value = false
}

onMounted(() => {
  // A fresh list on every mount, because groups change from the mod too.
  void voiceStore.requestGroupList()
})

onUnmounted(() => {
  // The list is refreshed on open, so nothing to tear down here.
})

async function joinGroup(groupId: string) {
  actionError.value = null
  busyGroupId.value = groupId
  try {
    // Der Store meldet Fehler über connectionNotice und wirft sie hier
    // zusätzlich, damit sie direkt an der Gruppe sichtbar werden.
    await voiceStore.joinChannel(groupId)
  } catch (error) {
    actionError.value = error instanceof Error ? error.message : 'Gruppe konnte nicht betreten werden'
  } finally {
    busyGroupId.value = null
  }
}

async function leaveGroup() {
  actionError.value = null
  try {
    await voiceStore.leaveChannel()
    emit('channel-selected')
  } catch (error) {
    actionError.value = error instanceof Error ? error.message : 'Gruppe konnte nicht verlassen werden'
  }
}

async function deleteGroup(groupId: string) {
  actionError.value = null
  busyGroupId.value = groupId
  try {
    await voiceStore.deleteChannel(groupId)
  } catch (error) {
    actionError.value = error instanceof Error ? error.message : 'Gruppe konnte nicht gelöscht werden'
  } finally {
    busyGroupId.value = null
  }
}

function confirmDelete(name: string): boolean {
  return window.confirm(`Gruppe "${name}" wirklich löschen?`)
}

async function createGroup() {
  const invalid = validateGroupName(newName.value)
  if (invalid) {
    createError.value = invalid
    return
  }

  createError.value = null
  isCreating.value = true
  try {
    const created = await voiceStore.createChannel({
      name: newName.value,
      type: newType.value,
      persistent: newPersistent.value,
    })
    if (created) {
      showCreateDialog.value = false
      newName.value = ''
      return
    }
    // The store already explained why in its notice, so the dialog shows it
    // right where the user clicked instead of only in the status line.
    createError.value = voiceStore.connectionNotice || 'Gruppe konnte nicht erstellt werden'
  } catch (error) {
    createError.value = error instanceof Error ? error.message : 'Gruppe konnte nicht erstellt werden'
  } finally {
    isCreating.value = false
  }
}
</script>

<template>
  <div class="channel-list">
    <div class="channel-header">
      <h3>Gruppen</h3>
      <div class="header-actions">
        <button
          class="btn btn-icon btn-sm"
          aria-label="Gruppenliste aktualisieren"
          title="Aktualisieren"
          @click="voiceStore.requestGroupList()"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M21 12a9 9 0 1 1-3-6.7" />
            <path d="M21 3v6h-6" />
          </svg>
        </button>
        <button class="btn btn-primary btn-sm" @click="openCreateDialog">+ Gruppe</button>
      </div>
    </div>

    <p v-if="actionError" class="inline-error" role="alert">{{ actionError }}</p>

    <ul class="channels" role="list" aria-label="Verfügbare Gruppen">
      <li
        v-for="group in groups"
        :key="group.id"
        class="channel-item"
        :class="{ active: currentGroupId === group.id }"
      >
        <div class="channel-main">
          <span class="channel-name" :title="group.name">{{ group.name }}</span>
          <span class="channel-meta">
            <span class="type-badge" :class="`type-${group.type}`" :title="typeDescription(group.type)">
              {{ typeLabel(group.type) }}
            </span>
            <span class="participant-count">{{ participantLabel(group) }}</span>
            <span v-if="group.persistent" class="persistent-badge" title="Bleibt nach einem Neustart erhalten">
              Persistent
            </span>
          </span>
        </div>

        <div class="channel-actions">
          <button
            v-if="currentGroupId !== group.id"
            class="btn btn-primary btn-xs"
            :disabled="busyGroupId === group.id"
            @click="joinGroup(group.id)"
          >
            Beitreten
          </button>
          <button
            v-else
            class="btn btn-secondary btn-xs"
            :disabled="busyGroupId === group.id"
            @click="leaveGroup"
          >
            Verlassen
          </button>
          <button
            class="btn btn-icon btn-xs btn-danger"
            :disabled="busyGroupId === group.id"
            :aria-label="`Gruppe ${group.name} löschen`"
            title="Gruppe löschen"
            @click="confirmDelete(group.name) && deleteGroup(group.id)"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polyline points="3 6 5 6 21 6" />
              <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
            </svg>
          </button>
        </div>
      </li>

      <li v-if="groups.length === 0" class="empty-state">
        <p>Keine Gruppen vorhanden</p>
        <button class="btn btn-primary btn-sm" @click="openCreateDialog">Erste Gruppe erstellen</button>
      </li>
    </ul>

    <div
      v-if="showCreateDialog"
      class="modal-overlay"
      role="presentation"
      @click.self="closeCreateDialog"
    >
      <div class="modal" role="dialog" aria-modal="true" aria-labelledby="create-group-title">
        <h3 id="create-group-title">Neue Gruppe erstellen</h3>

        <p v-if="createError" class="inline-error" role="alert">{{ createError }}</p>

        <div class="form-group">
          <label for="groupNameInput">Gruppenname</label>
          <input
            id="groupNameInput"
            v-model="newName"
            type="text"
            :maxlength="GROUP_NAME_MAX_LENGTH"
            placeholder="z. B. Allgemein, Gaming, Besprechung"
            autofocus
            @keyup.enter="createGroup"
          />
        </div>

        <div class="form-group">
          <label for="groupTypeInput">Typ</label>
          <select id="groupTypeInput" v-model="newType" class="setting-select">
            <option v-for="type in GROUP_TYPES" :key="type" :value="type">
              {{ GROUP_TYPE_LABELS[type] }} – {{ GROUP_TYPE_DESCRIPTIONS[type] }}
            </option>
          </select>
        </div>

        <div class="form-group">
          <label class="checkbox-label">
            <input v-model="newPersistent" type="checkbox" />
            Persistent – bleibt nach einem Neustart erhalten
          </label>
        </div>

        <div class="modal-actions">
          <button class="btn btn-secondary" :disabled="isCreating" @click="closeCreateDialog">Abbrechen</button>
          <button class="btn btn-primary" :disabled="!canCreate" @click="createGroup">
            {{ isCreating ? 'Erstelle...' : 'Erstellen' }}
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

